function pcParsePace(s){
  var t=String(s==null?'':s).trim();
  var m=t.match(/^(\d{1,3}):([0-5]?\d)$/);
  if(m) return (+m[1])*60 + (+m[2]);
  if(/^\d+(\.\d+)?$/.test(t)) return Math.round(parseFloat(t)*60);
  return null;
}
function pcParseTime(s){
  var t=String(s==null?'':s).trim();
  var m=t.match(/^(?:(\d{1,3}):)?(\d{1,3}):([0-5]?\d)$/);
  if(!m) return null;
  return (m[1]?(+m[1])*3600:0) + (+m[2])*60 + (+m[3]);
}
function pcFmt(sec){
  if(!isFinite(sec) || sec<0) return '--';
  sec=Math.round(sec);
  var h=Math.floor(sec/3600), m=Math.floor(sec%3600/60), s=sec%60;
  function p(n){ return (n<10?'0':'')+n; }
  return h ? h+':'+p(m)+':'+p(s) : m+':'+p(s);
}
function pcFromTime(totalSec, km){
  if(!(km>0)) return { error:'\u8ddd\u79bb\u5e94\u5927\u4e8e 0' };
  if(!(totalSec>0)) return { error:'\u65f6\u95f4\u5e94\u5927\u4e8e 0' };
  var pace=totalSec/km;
  return { error:null, pace:pace, speed: km/(totalSec/3600), paceMile: pace*1.609344 };
}
function pcFromPace(paceSec, km){
  if(!(km>0)) return { error:'\u8ddd\u79bb\u5e94\u5927\u4e8e 0' };
  if(!(paceSec>0)) return { error:'\u914d\u901f\u5e94\u5927\u4e8e 0' };
  return { error:null, total: paceSec*km, speed: 3600/paceSec };
}
function pcSplits(paceSec, km, step){
  step = step || 1;
  var out=[];
  for(var d=step; d<=km+1e-9; d+=step) out.push({ km:Math.round(d*100)/100, cum:paceSec*d });
  var last=out.length? out[out.length-1].km : 0;
  if(km-last > 1e-9) out.push({ km:Math.round(km*100)/100, cum:paceSec*km });
  return out;
}
var PC_RACES = [['5K',5],['10K',10],['\u534a\u7a0b',21.0975],['\u5168\u7a0b',42.195]];
function pcRiegel(knownSec, knownKm, targetKm){
  if(!(knownSec>0 && knownKm>0 && targetKm>0)) return null;
  return knownSec * Math.pow(targetKm/knownKm, 1.06);
}
function pcPredict(knownSec, knownKm){
  return PC_RACES.map(function(r){
